export function applyUserProperties(properties) {
	if (properties.hasOwnProperty('animationspeed')) {
		animation.x = properties.animationspeed;
	}
	if (properties.hasOwnProperty('animationamplitude')) {
		animation.y = properties.animationamplitude;
	}
	if (properties.hasOwnProperty('animationshift')) {
		animation.z = properties.animationshift;
	}
}

/**
 * @param {Vec3} value - for property 'origin'
 * @return {Vec3} - update current property value
 */
export function init(value) {
    origin = value;
	return value;
}

/**
 * @param {Vec3} value - for property 'origin'
 * @return {Vec3} - update current property value
 */
export function update(value) {
	value.y = origin.y + (
		Math.sin(engine.runtime * animation.x + animation.z * 2) * animation.y
	);
	return value;
}

