'use strict';

let isResolutionChanged = true;

let origin = new Vec2();


export function applyUserProperties(properties) {
	if (properties.hasOwnProperty('aspectratio')
		|| properties.hasOwnProperty('autoresolution')
		|| properties.hasOwnProperty('resolutionx')
		|| properties.hasOwnProperty('resolutiony')) {
		isResolutionChanged = true;
	}
}

/**
 * @param {Vec3} value - screen resolution
 */
export function resizeScreen(value) {
	isResolutionChanged = true;
}

/**
 * @param {Vec3} value - for property 'origin'
 * @return {Vec3} - update current property value
 */
export function init(value) {
	origin = value;
	return value;
}

/**
 * @param {Vec3} value - for property 'origin'
 * @return {Vec3} - update current property value
 */
export function update(value) {
	if (isResolutionChanged) {
		isResolutionChanged = false;

		let newOrigin = shared.getPosition(origin);

		value.x = newOrigin.x;
		value.y = newOrigin.y;
	}

	return value;
}

